"""methods.json catalog: precision contracts for every compiled method ID used by the campaign driver.
Facts here describe the actual implementation in src/mp_core.cuh / src/mpsolve.cu (custom code) or the documented/probed
behaviour of vendor routines (cuSOLVER 11.7.1 / CUDA 12.6, MAGMA 2.9.0). Unknown vendor internals are stated as unknown."""
SRC = 'source/src/mp_core.cuh'
STOP = ('production stopping: stop when eta_j<=tau and omega_j<=tau for every RHS, evaluated in FP64 on the original stored system each outer step; '
        'also stop on nonfinite values, stagnation (eta_max fails to decrease by 10% for 3 consecutive steps), max_outer=30, or GMRES global budget exhaustion')
RESID64 = ('residual r=b-Ax with stored A (FP32 or FP64 entries promoted exactly), FP64 iterate copy, FP64 fused multiply-add accumulation, '
           'sequential over columns per row (deterministic order), denominators |A||x|+|b| accumulated in the same pass (src/mp_kernels.cuh k_resid)')
PIV = 'LAPACK-style partial pivoting (row interchanges), 1-based pivot vector, P A = L U with unit lower L'
CS32 = ('cuSOLVER cusolverDnXgetrf (CUDA_R_32F data and compute) on the FP32 copy of A (storage rounding of FP64 inputs when applicable); '
        'internal panel/blocking/trailing arithmetic: vendor FP32, details not published (precision_source=documented for FP32 operands, unknown for internal kernel structure)')
CS64 = 'cuSOLVER cusolverDnXgetrf (CUDA_R_64F) on an FP64 copy of A; vendor FP64 internals'
HET16 = ('custom right-looking blocked LU (src/mp_core.cuh custom_blocked_lu): global power-of-two scaling so max|A| in [0.5,1); FP32 storage; '
         'panel (n_rem x nb, nb=512) factored by cusolverDnXgetrf in FP32 with partial pivoting; row interchanges applied to the full row by a custom kernel; '
         'U12 by cublasStrsm (FP32); trailing update A22 -= L21*U12 with L21 and U12 converted to FP16 (round-to-nearest, overflow/subnormal events counted), '
         'cublasGemmEx CUDA_R_16F operands, CUBLAS_COMPUTE_32F accumulation, FP32 output, tensor-core algorithm requested (CUBLAS_GEMM_DEFAULT_TENSOR_OP); '
         'Schur complement stored FP32. This is a heterogeneous FP32/FP16 factorization, NOT pure FP16 LU')
CUS32 = HET16.replace('with L21 and U12 converted to FP16 (round-to-nearest, overflow/subnormal events counted), cublasGemmEx CUDA_R_16F operands, CUBLAS_COMPUTE_32F accumulation, FP32 output, tensor-core algorithm requested (CUBLAS_GEMM_DEFAULT_TENSOR_OP)', 'by cublasSgemm (FP32 operands, FP32 accumulation, default math mode, no tensor-core down-conversion)').replace('heterogeneous FP32/FP16 factorization, NOT pure FP16 LU', 'same-code-path FP32 control for the heterogeneous method (promotion-gate comparator)')
TRS32 = 'correction/initial triangular solves: residual cast FP64->FP32, cusolverDnXgetrs (CUDA_R_32F) with the FP32 factors, result cast back to FP64; then unscaled by the power-of-two factors (exact)'
TRS64 = 'triangular solves: cusolverDnXgetrs (CUDA_R_64F) with FP64 factors'
GMRES = ('inner solver: right-preconditioned flexible GMRES (FGMRES) on A d = r for each RHS independently sharing the same factors: z_j = M^{-1} v_j via the factor application above, '
         'w = A z_j with the ORIGINAL stored A in FP64 (same kernel as the residual), modified Gram-Schmidt (one pass, device-resident dot products and axpy), FP64 basis V and Z on device, '
         'Givens rotations and the small least-squares problem in FP64 on the host, d = Z y; true residual ||r-Ad||_2/||r||_2 recomputed in FP64 before accepting; restart m=40, inner tolerance 1e-4 '
         '(recursive), up to 4 cycles per correction, global inner budget 480 per solve; happy breakdown verified with the true residual (src/mp_core.cuh Engine::gmres_solve)')
LEFT = ('inner solver: left-preconditioned GMRES (paper-aligned operator C(v)=U^{-1}L^{-1}P(Av), g=U^{-1}L^{-1}P r): A v in FP64 with the stored A; preconditioner application in the stated precision; '
        'basis V FP64, MGS one pass, d = V y (never Z y), single cycle (no restart) of up to m=40 steps, true original-coordinate residual recomputed before acceptance')

def ir(mid, name, factor, working, resid, apply, extra='', scaling='none', fallback='no fallback (fixed method)', paper='Carson & Higham 2018 Alg. 1.1 (standard IR) with u_f,u,u_r as stated', gm=None):
    pc = dict(stored_input='as case dtype (FP32 or FP64 A and B)', target_format=f'FP{working} iterate returned (saved X dtype float{working})', iterate_update_format=f'FP{working} iterate x, FP64 correction d added in FP{working} (x += d rounded to FP{working})',
              factorization=factor, factor_storage=('FP32' if 'cs64' not in factor and 'FP64 copy' not in factor else 'FP64'), pivoting=PIV, initial_solve=apply, correction_solve=apply,
              residual=RESID64 if resid == 64 else 'single-precision residual control: r = b - A x computed in FP32 arithmetic (fmaf accumulation) from the stored FP32 A, x, b (src/mp_kernels.cuh k_resid_f32); eta from this r; omega not evaluated in-loop',
              scaling=scaling, ftz_subnormal='GPU default (no FTZ flag; FP16 conversions count subnormal/overflow events)', fused_ops='FMA used in residual kernels and cuBLAS kernels; FP16 conversion separate from GEMM', gmres=gm or 'none (stationary refinement)', fallback=fallback, fallback_visibility='explicit: stages and stage times recorded per trial')
    return dict(method_id=mid, display_name=name, algorithm='LU with partial pivoting + iterative refinement' + (' (GMRES-IR)' if gm else ''), backend='cuSOLVER 11.7.1 (CUDA 12.6) factors/solves, cuBLAS 12.6 GEMM/TRSM, custom CUDA kernels; driver mpsolve (this campaign)', backend_version='cuSOLVER 11.7.1.2, cuBLAS 12.6.4.1, CUDA runtime 12.6, driver 570.133.20, sm_70', source_entrypoint=SRC + ' Engine::run / refine_stage', precision_contract=pc, stopping=STOP, paper_mapping=paper, precision_source='source_audited (custom code), documented (vendor FP32/FP64 operand types), unknown (vendor kernel internals)', extra=extra)

def direct(mid, name, factor, working, apply, backend, src=SRC + ' Engine::run (max_outer=0)', scaling='none'):
    return dict(method_id=mid, display_name=name, algorithm='LU with partial pivoting, single direct solve (no refinement)', backend=backend, backend_version='cuSOLVER 11.7.1.2 / cuBLAS 12.6.4.1 / CUDA 12.6 / MAGMA 2.9.0 where named', source_entrypoint=src,
                precision_contract=dict(stored_input='as case dtype', target_format=f'FP{working}', factorization=factor, pivoting=PIV, solve=apply, residual='none inside the method; external FP64 validation only', scaling=scaling, fallback='none'), stopping='none (direct solve); qualification determined externally', paper_mapping='ordinary LU baseline (control)', precision_source='documented (vendor operand types); internals unknown')

def irs(mid, main, low, mode, fb, tol):
    return dict(method_id=mid, display_name=f'cuSOLVER IRS Xgesv main FP{main} lowest {low} {mode} fallback={fb} tol={tol}', algorithm='vendor mixed-precision iterative refinement solver (cusolverDnIRSXgesv)', backend='cuSOLVER 11.7.1 cusolverDnIRSXgesv', backend_version='cuSOLVER 11.7.1.2 (CUDA 12.6)', source_entrypoint='source/src/mp_core.cuh IRSRunner::run',
                precision_contract=dict(stored_input=f'FP{main} A copied into a work buffer each call (restoration counted in time); B copied to a private FP{main} buffer', target_format=f'FP{main} X', main_precision=f'CUSOLVER_R_{main}F (documented)', lowest_precision=low + ' (documented request; actual internal factorization/solve/residual arithmetic NOT observable: precision_source=unknown)', refinement=mode + ' (documented mode name; iteration semantics vendor-defined)',
                                        pivoting='vendor LU with pivoting (documented); permutation not exposed', residual='vendor-internal; not observable', scaling='unknown', fallback=('enabled: if niters<0 the solver falls back to a main-precision factorization (observed via sign of niters only)' if fb else 'disabled by cusolverDnIRSParamsDisableFallback'), fallback_visibility='partial (sign of niters); stage costs not exposed', stopping=('vendor default tolerance (unknown mapping to our acceptance test)' if tol == 'default' else 'cusolverDnIRSParamsSetTol/TolInner set to 100*u_target (mapping to our acceptance test not assumed)'), max_iters='SetMaxIters 50, SetMaxItersInner 50'),
                stopping='vendor stopping rule; external original-system validation decides qualification', paper_mapping='Haidar et al. 2020 style tensor-core IR (vendor implementation); classical/GMRES modes per cuSOLVER docs', precision_source='documented/probed; internals unknown', limits='GMRES modes accept nrhs=1 only (CUSOLVER_STATUS 21 observed for nrhs>1); BF16/TF32 lowest precision rejected on sm_70 (bufferSize status 4)')

def magma(mid, name, algo, facto, solver):
    return dict(method_id=mid, display_name=name, algorithm=algo, backend='MAGMA 2.9.0 (built from source, GPU_TARGET=Volta, OpenBLAS 0.3.34 for host panels, 8 OpenBLAS threads pinned to cores 0-7)', backend_version='MAGMA 2.9.0 (January 2025) + cuBLAS 12.6', source_entrypoint='source/src/mpsolve.cu MagmaRunner::run',
                precision_contract=dict(stored_input='FP64 A copied into a MAGMA work buffer each call; B copied to a private buffer', target_format='FP64 X', factorization=facto, refinement=solver, pivoting='MAGMA partial pivoting (ipiv host + device copies)', residual='vendor-internal FP64 (source: src/dxgesv_gmres_gpu.cpp uses dgemm residual in FP64; stopping uses ||r||<=||x||*||A||*eps*sqrt(n) style BWDMAX rule)', scaling='none observed in source (equilibration code commented out in dxgesv_gmres_gpu.cpp)', fallback='MAGMA falls back to FP64 LU when iter<0 (README_FP16_Iterative_Refinement.txt); observed via sign of iter', fallback_visibility='partial (sign of iter), stage costs not exposed'),
                stopping='vendor stopping rule; external original-system validation decides qualification', paper_mapping='Haidar, Tomov, Dongarra, Higham SC18 / Haidar et al. 2020 (vendor implementation of FP16-TC LU + IR/GMRES-IR)', precision_source='source_audited for the driver structure (MAGMA source read), unknown for kernel-level arithmetic', limits='GMRES-based modes (GMSTRS) returned an all-zero solution for nrhs>1 (unsupported, detected by validation); SHT+IRSTRS produced NaN after 208 iterations on one n=1024 kappa=1e4 case while reporting convergence; htgetrf with n<=nb factors entirely in FP32')

